if(p==='/api/rsvp'&&req.method==='POST'){let d=await req.json();const phone=String(d.whatsapp||'').replace(/[\s()-]/g,'').replace(/^00/,'+');if(typeof d.name!=='string'||!d.name.trim()||d.name.length>100||!/^\+[1-9]\d{7,14}$/.test(phone)||(d.guests!==undefined&&+d.guests!==1)||!['yes','no'].includes(d.attending))return json({error:'Enter your full name and WhatsApp number with country code. Each RSVP is for one individual.'},400);let id=crypto.randomUUID();await put('rsvp/'+id,{id,name:d.name.trim(),whatsapp:phone,whatsappConsent:d.whatsappConsent===true,consentText:d.whatsappConsent===true?'I agree to receive WhatsApp RSVP approval or decline updates from Vimbai and Clarence.':null,consentedAt:d.whatsappConsent===true?new Date().toISOString():null,guests:1,guestNames:d.name.trim(),attending:d.attending,status:d.attending==='yes'?'pending':'declined',created:new Date().toISOString()});return json({id})}
if(p==='/api/messaging-status'){if(!admin)return json({error:'Please sign in'},401);return json(env.WHATSAPP_STATUS||{enabled:false,missing:[],switchedOn:false})}
if(p.startsWith('/api/export/')){if(!admin)return json({error:'Please sign in'},401);let rows,headers,filename;if(p==='/api/export/guests.csv'){const guests=await Promise.all((await list('rsvp/')).map(o=>get(o.key)));headers=['Guest names','Number attending','RSVP submitted by','WhatsApp','Status'];rows=guests.filter(r=>r.status==='approved').map(r=>[r.guestNames||r.name,r.guests,r.name,r.whatsapp||'',r.status]);filename='attending-guests.csv'}else if(p==='/api/export/gifts.csv'){const gifts=await Promise.all((await list('gifts/')).map(o=>get(o.key)));headers=['Giver name','Gift description','Submitted at'];rows=gifts.map(g=>[g.name,g.description,g.created]);filename='wedding-gifts.csv'}else return json({error:'Not found'},404);const cell=v=>{let t=String(v??'');if(/^[\s]*[=+@-]/.test(t)||/^[\t\r\n]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"'};const csv='\uFEFF'+[headers,...rows].map(row=>row.map(cell).join(',')).join('\r\n')+'\r\n';return new Response(csv,{headers:{'Content-Type':'text/csv; charset=utf-8','Content-Disposition':'attachment; filename="'+filename+'"','Cache-Control':'no-store'}})}
if(p==='/api/guestbook'){if(req.method==='POST'){let d=await req.json();if(typeof d.firstName!=='string'||!d.firstName.trim()||d.firstName.length>100||typeof d.surname!=='string'||!d.surname.trim()||d.surname.length>100||typeof d.message!=='string'||!d.message.trim()||d.message.length>3000)return json({error:'Please enter your name, surname and message.'},400);const id=crypto.randomUUID();await put('guestbook/'+id,{id,firstName:d.firstName.trim(),surname:d.surname.trim(),message:d.message.trim(),created:new Date().toISOString()});return json({ok:true})}if(req.method==='GET'){if(!admin)return json({error:'Please sign in'},401);return json(await Promise.all((await list('guestbook/')).map(o=>get(o.key))))}return json({error:'Method not allowed'},405)}
if(p==='/api/gifts'){if(req.method==='POST'){let d=await req.json();if(typeof d.name!=='string'||!d.name.trim()||d.name.length>100||typeof d.description!=='string'||!d.description.trim()||d.description.length>2000)return json({error:'Please enter your name and what you gave as a gift.'},400);const id=crypto.randomUUID();await put('gifts/'+id,{id,name:d.name.trim(),description:d.description.trim(),created:new Date().toISOString()});return json({ok:true})}if(req.method==='GET'){if(!admin)return json({error:'Please sign in'},401);return json(await Promise.all((await list('gifts/')).map(o=>get(o.key))))}return json({error:'Method not allowed'},405)}
if(p==='/api/admin'){if(!admin)return json({error:'Incorrect password'},401);if(req.method==='POST'){let d=await req.json();if(typeof d.id!=='string'||!/^[-a-zA-Z0-9]+$/.test(d.id))return json({error:'Invalid response ID'},400);const run=async()=>{let r=await get('rsvp/'+d.id);if(!r)return json({error:'Response not found'},404);const retry=d.action==='retry_whatsapp';if(retry){if(!['approved','declined'].includes(r.status)||!['failed','not_configured'].includes(r.whatsappNotification?.status))return json({error:'Check the previous result before attempting another message.'},409)}else if(!['approved','declined'].includes(d.status))return json({error:'Invalid RSVP decision'},400);const changed=!retry&&r.status!==d.status;if(!retry)r.status=d.status;await put('rsvp/'+r.id,r);if(changed||retry){const config={...defaults,...(await get('settings')||{})};r.whatsappNotification={status:'sending',decision:r.status,attemptedAt:new Date().toISOString(),attemptId:crypto.randomUUID()};await put('rsvp/'+r.id,r);const result=env.WHATSAPP_NOTIFY?await env.WHATSAPP_NOTIFY({...r,weddingDate:config.date,weddingTime:config.time||'13:30'}):{status:'not_configured',detail:'WhatsApp is not connected. The RSVP decision is saved.'};r.whatsappNotification={...r.whatsappNotification,...result};await put('rsvp/'+r.id,r)}return json({ok:true,notification:r.whatsappNotification||null})};return env.WITH_RSVP_LOCK?env.WITH_RSVP_LOCK(d.id,run):run()}return json(await Promise.all((await list('rsvp/')).map(o=>get(o.key))))}
